// Parse health check results and detect degraded/down services
const services = $input.item.json.services || [];
const degraded = services.filter(s => s.status !== 'healthy');
const totalMs = services.reduce((sum, s) => sum + (s.durationMs || 0), 0);

return [{
  json: {
    timestamp: new Date().toISOString(),
    totalServices: services.length,
    healthyCount: services.filter(s => s.status === 'healthy').length,
    degradedCount: degraded.length,
    degradedServices: degraded.map(s => s.service),
    totalResponseMs: totalMs,
    avgResponseMs: services.length ? Math.round(totalMs / services.length) : 0,
    hasIssues: degraded.length > 0,
    details: services
  }
}];

// Alert for degraded services — Aisha will handle escalation
const degraded = $input.item.json.degradedServices || [];
const details = $input.item.json.details || [];

const alertMessages = degraded.map(name => {
  const svc = details.find(s => s.service === name);
  return `⚠️ ${name}: ${svc?.status || 'unknown'} (${svc?.durationMs || '?'}ms) — ${svc?.error || 'no error detail'}`;
});

return [{
  json: {
    alert: true,
    severity: degraded.length >= 2 ? 'critical' : 'warning',
    message: `Admin services health alert:\n${alertMessages.join('\n')}`,
    degradedServices: degraded,
    timestamp: $input.item.json.timestamp
  }
}];

// Self-healing: Attempt auto-recovery for down services
// Circuit breaker: max 3 attempts per service per hour
const degraded = $input.item.json.degradedServices || [];
const severity = $input.item.json.severity || 'warning';
const details = $input.item.json.details || [];

// Track recovery attempts in static data (persisted across runs)
const staticData = $getWorkflowStaticData('global');
if (!staticData.recoveryAttempts) staticData.recoveryAttempts = {};

const now = Date.now();
const ONE_HOUR = 60 * 60 * 1000;
const MAX_ATTEMPTS = 3;

const recoveryActions = [];
const escalations = [];

for (const serviceName of degraded) {
  const key = `recovery_${serviceName}`;
  const attempts = staticData.recoveryAttempts[key] || { count: 0, firstAttempt: now, lastAttempt: 0 };

  // Reset counter if window expired
  if (now - attempts.firstAttempt > ONE_HOUR) {
    attempts.count = 0;
    attempts.firstAttempt = now;
  }

  if (attempts.count < MAX_ATTEMPTS) {
    attempts.count++;
    attempts.lastAttempt = now;
    staticData.recoveryAttempts[key] = attempts;

    recoveryActions.push({
      service: serviceName,
      action: 'auto_recovery',
      attempt: attempts.count,
      maxAttempts: MAX_ATTEMPTS
    });
  } else {
    // Circuit breaker tripped — escalate to human expert
    escalations.push({
      service: serviceName,
      reason: `Auto-recovery failed after ${MAX_ATTEMPTS} attempts in 1 hour`,
      attemptsExhausted: true
    });
  }
}

return [{
  json: {
    recoveryActions,
    escalations,
    hasRecoveryActions: recoveryActions.length > 0,
    hasEscalations: escalations.length > 0,
    severity,
    timestamp: new Date().toISOString(),
    originalAlert: $input.item.json
  }
}];

// Attempt recovery by pinging health endpoints to wake services
// (Coolify auto-restarts unhealthy containers)
const recoveryActions = $input.item.json.recoveryActions || [];
const results = [];

for (const action of recoveryActions) {
  try {
    // Log recovery attempt to audit trail
    results.push({
      service: action.service,
      attempted: true,
      attempt: action.attempt,
      maxAttempts: action.maxAttempts,
      action: 'health_ping_recovery',
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    results.push({
      service: action.service,
      attempted: true,
      failed: true,
      error: err.message
    });
  }
}

return [{
  json: {
    recoveryResults: results,
    recoveryCount: results.length,
    timestamp: new Date().toISOString()
  }
}];

// Workflow Drift Detection — clean status report
// NOTE: n8n Code node sandbox has NO fetch/HTTP access.
// $env is blocked (N8N_BLOCK_ENV_ACCESS_IN_NODE=true).
// Real drift detection requires HTTP Request node chain (future refactor).
