  'WF_ADMIN_ORCHESTRATION',
  'WF_APPROVAL_GATE',
  'WF_COMPLIANCE_AGENT',
  'WF_COMPLIANCE_REROUTE',
  'WF_DELIVERY_AGENT',
  'WF_DIRIGENT_AGENT',
  'WF_EXPERT_NOTIFICATION',
  'WF_KNOWLEDGE_AGENT',
  'WF_LANGFUSE_PERFORMANCE_REVIEW',
  'WF_MCP_BRIDGE',
  'WF_MODEL_ROUTER',
  'WF_NIGHTLY_STORY_AUDIT',
  'WF_NODE_FACTORY',
  'WF_PR_COMPLIANCE_GATE',
  'WF_SELF_DEPLOY'
