    workflowDrift: false,
    skipped: true,
    reason: 'Code sandbox has no HTTP access — drift detection via HTTP Request node (TODO)',
    missingWorkflows: [],
    inactiveWorkflows: [],
    totalExpected: EXPECTED_WORKFLOWS.length,
    totalFound: EXPECTED_WORKFLOWS.length,
    timestamp: new Date().toISOString()
  }
}];
